export function decodeReport(v: xdr.ScVal): Report {
  const f = rt.decodeStruct(v, "Report");
  return {
    created_ledger: rt.decodeU32(rt.field(f, "created_ledger")),
    post_id: rt.decodeU64(rt.field(f, "post_id")),
    reason_hash: rt.decodeBytesN(rt.field(f, "reason_hash"), 32),
    reporter: rt.decodeAddress(rt.field(f, "reporter")),
    stake_amount: rt.decodeI128(rt.field(f, "stake_amount")),
    status: decodeReportStatus(rt.field(f, "status")),
    token: rt.decodeAddress(rt.field(f, "token")),
    weight_bps: rt.decodeU32(rt.field(f, "weight_bps")),
  };
}

