/**
 * Withdraw from a pool. Requires `threshold` valid admin signatures.
 *
 * `min_out_amount` is the minimum amount the recipient must receive. The
 * received amount is `requested - requested * fee_bps / 10_000` (see
 * `pool_withdraw_received_amount`); when it is below `min_out_amount` the
 * withdrawal reverts with `"slippage exceeded"` and publishes a
 * `WithdrawalSlippageExceededEvent`.
 *
 * `deadline` is a Unix timestamp: once the ledger timestamp is past it the
 * withdrawal reverts with `"deadline expired"`.
 */
export interface PoolWithdrawArgs {
  signers: Array<string>;
  pool_id: string;
  amount: bigint;
  recipient: string;
  min_out_amount: bigint | null;
  deadline: bigint | null;
}

/** Arguments of `pool_withdraw`, in call order. */
export function encodePoolWithdrawArgs(args: PoolWithdrawArgs): xdr.ScVal[] {
  return [
    rt.encodeVec(args.signers, (v31) => rt.encodeAddress(v31)),
    rt.encodeSymbol(args.pool_id),
    rt.encodeI128(args.amount),
    rt.encodeAddress(args.recipient),
    rt.encodeOption(args.min_out_amount, (v32) => rt.encodeI128(v32)),
    rt.encodeOption(args.deadline, (v33) => rt.encodeU64(v33)),
  ];
}

/** Return value of `pool_withdraw`. */
export function decodePoolWithdrawResult(v: xdr.ScVal): void {
  rt.decodeVoid(v);
}

