export interface TipEvent {
  version: number;
  tipper: string;
  post_id: bigint;
  amount: bigint;
  fee: bigint;
}

/** Leading topic(s) identifying `TipEvent`. */
export const TIP_EVENT_TOPICS = ["tip_event"] as const;

export function decodeTipEvent(topics: xdr.ScVal[], data: xdr.ScVal): TipEvent {
  rt.expectTopics(topics, TIP_EVENT_TOPICS, 3, "TipEvent");
  const d = rt.decodeStruct(data, "TipEvent");
  return {
    version: rt.decodeU32(rt.item(topics, 1)),
    tipper: rt.decodeAddress(rt.item(topics, 2)),
    post_id: rt.decodeU64(rt.item(topics, 3)),
    amount: rt.decodeI128(rt.field(d, "amount")),
    fee: rt.decodeI128(rt.field(d, "fee")),
  };
}

