/**
 * Published when a withdrawal would deliver less than the caller's
 * `min_out_amount`. The withdrawal then reverts, so the event is rolled back
 * with the failed invocation and is only observable in the failed-call
 * diagnostics (it never lands in the committed ledger events).
 */
export interface WithdrawalSlippageExceededEvent {
  version: number;
  pool_id: string;
  requested_amount: bigint;
  received_amount: bigint;
  min_out_amount: bigint;
}

/** Leading topic(s) identifying `WithdrawalSlippageExceededEvent`. */
export const WITHDRAWAL_SLIPPAGE_EXCEEDED_EVENT_TOPICS = ["withdrawal_slippage_exceeded"] as const;

export function decodeWithdrawalSlippageExceededEvent(
  topics: xdr.ScVal[],
  data: xdr.ScVal
): WithdrawalSlippageExceededEvent {
  rt.expectTopics(
    topics,
    WITHDRAWAL_SLIPPAGE_EXCEEDED_EVENT_TOPICS,
    2,
    "WithdrawalSlippageExceededEvent"
  );
  const d = rt.decodeStruct(data, "WithdrawalSlippageExceededEvent");
  return {
    version: rt.decodeU32(rt.item(topics, 1)),
    pool_id: rt.decodeSymbol(rt.item(topics, 2)),
    requested_amount: rt.decodeI128(rt.field(d, "requested_amount")),
    received_amount: rt.decodeI128(rt.field(d, "received_amount")),
    min_out_amount: rt.decodeI128(rt.field(d, "min_out_amount")),
  };
}

/** Any event this contract emits, tagged by its spec name. */
export type ContractEvent =
  | { name: "TipEvent"; event: TipEvent }
  | { name: "BlockEvent"; event: BlockEvent }
  | { name: "FollowEvent"; event: FollowEvent }
  | { name: "PausedEvent"; event: PausedEvent }
  | { name: "PostDeleted"; event: PostDeleted }
  | { name: "GovVoteEvent"; event: GovVoteEvent }
  | { name: "UnblockEvent"; event: UnblockEvent }
  | { name: "LikePostEvent"; event: LikePostEvent }
  | { name: "RentPaidEvent"; event: RentPaidEvent }
  | { name: "UnfollowEvent"; event: UnfollowEvent }
  | { name: "UnpausedEvent"; event: UnpausedEvent }
  | { name: "FeeUpdatedEvent"; event: FeeUpdatedEvent }
  | { name: "ProfileSetEvent"; event: ProfileSetEvent }
  | { name: "AppealFiledEvent"; event: AppealFiledEvent }
  | { name: "ContractUpgraded"; event: ContractUpgraded }
  | { name: "PoolCreatedEvent"; event: PoolCreatedEvent }
  | { name: "PoolDepositEvent"; event: PoolDepositEvent }
  | { name: "PostCreatedEvent"; event: PostCreatedEvent }
  | { name: "RoleGrantedEvent"; event: RoleGrantedEvent }
  | { name: "RoleRevokedEvent"; event: RoleRevokedEvent }
  | { name: "ModulePausedEvent"; event: ModulePausedEvent }
  | { name: "PoolWithdrawEvent"; event: PoolWithdrawEvent }
  | { name: "PostReportedEvent"; event: PostReportedEvent }
  | { name: "PostRevealedEvent"; event: PostRevealedEvent }
  | { name: "PostCommittedEvent"; event: PostCommittedEvent }
  | { name: "AppealResolvedEvent"; event: AppealResolvedEvent }
  | { name: "DmKeyPublishedEvent"; event: DmKeyPublishedEvent }
  | { name: "GovAppealFiledEvent"; event: GovAppealFiledEvent }
  | { name: "GovAppealVotedEvent"; event: GovAppealVotedEvent }
  | { name: "ModuleUnpausedEvent"; event: ModuleUnpausedEvent }
  | { name: "PoolAdminAddedEvent"; event: PoolAdminAddedEvent }
  | { name: "ProfileDeletedEvent"; event: ProfileDeletedEvent }
  | { name: "ProposalSignedEvent"; event: ProposalSignedEvent }
  | { name: "EmergencyBypassEvent"; event: EmergencyBypassEvent }
  | { name: "ProposalCreatedEvent"; event: ProposalCreatedEvent }
  | { name: "ReportDismissedEvent"; event: ReportDismissedEvent }
  | { name: "TreasuryUpdatedEvent"; event: TreasuryUpdatedEvent }
  | { name: "PoolAdminRemovedEvent"; event: PoolAdminRemovedEvent }
  | { name: "ProposalExecutedEvent"; event: ProposalExecutedEvent }
  | { name: "GovAppealResolvedEvent"; event: GovAppealResolvedEvent }
  | { name: "GovProposalVetoedEvent"; event: GovProposalVetoedEvent }
  | { name: "CredentialVerifiedEvent"; event: CredentialVerifiedEvent }
  | { name: "GovProposalCreatedEvent"; event: GovProposalCreatedEvent }
  | { name: "PostContentHashSetEvent"; event: PostContentHashSetEvent }
  | { name: "AttestationVerifiedEvent"; event: AttestationVerifiedEvent }
  | { name: "GovProposalExecutedEvent"; event: GovProposalExecutedEvent }
  | { name: "PoolThresholdUpdatedEvent"; event: PoolThresholdUpdatedEvent }
  | { name: "CredentialRootUpdatedEvent"; event: CredentialRootUpdatedEvent }
  | { name: "PostRemovedByModerationEvent"; event: PostRemovedByModerationEvent }
  | { name: "WithdrawalSlippageExceededEvent"; event: WithdrawalSlippageExceededEvent };

/**
 * Decode a contract event from its topics and data, or return `null` when
 * the topics do not belong to an event of this contract.
 */
export function decodeEvent(topics: xdr.ScVal[], data: xdr.ScVal): ContractEvent | null {
  const first = topics[0];
  if (!first || first.switch() !== xdr.ScValType.scvSymbol()) return null;
  switch (first.sym().toString()) {
    case "tip_event":
      return { name: "TipEvent", event: decodeTipEvent(topics, data) };
    case "block_event":
      return { name: "BlockEvent", event: decodeBlockEvent(topics, data) };
    case "follow_event":
      return { name: "FollowEvent", event: decodeFollowEvent(topics, data) };
    case "paused_event":
      return { name: "PausedEvent", event: decodePausedEvent(topics, data) };
    case "post_deleted":
      return { name: "PostDeleted", event: decodePostDeleted(topics, data) };
    case "gov_vote_event":
      return { name: "GovVoteEvent", event: decodeGovVoteEvent(topics, data) };
    case "unblock_event":
      return { name: "UnblockEvent", event: decodeUnblockEvent(topics, data) };
    case "like_post_event":
      return { name: "LikePostEvent", event: decodeLikePostEvent(topics, data) };
    case "rent_paid_event":
      return { name: "RentPaidEvent", event: decodeRentPaidEvent(topics, data) };
    case "unfollow_event":
      return { name: "UnfollowEvent", event: decodeUnfollowEvent(topics, data) };
    case "unpaused_event":
      return { name: "UnpausedEvent", event: decodeUnpausedEvent(topics, data) };
    case "fee_updated_event":
      return { name: "FeeUpdatedEvent", event: decodeFeeUpdatedEvent(topics, data) };
    case "profile_set_event":
      return { name: "ProfileSetEvent", event: decodeProfileSetEvent(topics, data) };
    case "appeal_filed_event":
      return { name: "AppealFiledEvent", event: decodeAppealFiledEvent(topics, data) };
    case "contract_upgraded":
      return { name: "ContractUpgraded", event: decodeContractUpgraded(topics, data) };
    case "pool_created_event":
      return { name: "PoolCreatedEvent", event: decodePoolCreatedEvent(topics, data) };
    case "pool_deposit_event":
      return { name: "PoolDepositEvent", event: decodePoolDepositEvent(topics, data) };
    case "post_created_event":
      return { name: "PostCreatedEvent", event: decodePostCreatedEvent(topics, data) };
    case "role_granted_event":
      return { name: "RoleGrantedEvent", event: decodeRoleGrantedEvent(topics, data) };
    case "role_revoked_event":
      return { name: "RoleRevokedEvent", event: decodeRoleRevokedEvent(topics, data) };
    case "module_paused_event":
      return { name: "ModulePausedEvent", event: decodeModulePausedEvent(topics, data) };
    case "pool_withdraw_event":
      return { name: "PoolWithdrawEvent", event: decodePoolWithdrawEvent(topics, data) };
    case "post_reported_event":
      return { name: "PostReportedEvent", event: decodePostReportedEvent(topics, data) };
    case "post_revealed_event":
      return { name: "PostRevealedEvent", event: decodePostRevealedEvent(topics, data) };
    case "post_committed_event":
      return { name: "PostCommittedEvent", event: decodePostCommittedEvent(topics, data) };
    case "appeal_resolved_event":
      return { name: "AppealResolvedEvent", event: decodeAppealResolvedEvent(topics, data) };
    case "dm_key_published_event":
      return { name: "DmKeyPublishedEvent", event: decodeDmKeyPublishedEvent(topics, data) };
    case "appeal_filed":
      return { name: "GovAppealFiledEvent", event: decodeGovAppealFiledEvent(topics, data) };
    case "appeal_voted":
      return { name: "GovAppealVotedEvent", event: decodeGovAppealVotedEvent(topics, data) };
    case "module_unpaused_event":
      return { name: "ModuleUnpausedEvent", event: decodeModuleUnpausedEvent(topics, data) };
    case "pool_admin_added_event":
      return { name: "PoolAdminAddedEvent", event: decodePoolAdminAddedEvent(topics, data) };
    case "profile_deleted_event":
      return { name: "ProfileDeletedEvent", event: decodeProfileDeletedEvent(topics, data) };
    case "proposal_signed_event":
      return { name: "ProposalSignedEvent", event: decodeProposalSignedEvent(topics, data) };
    case "emergency_bypass_event":
      return { name: "EmergencyBypassEvent", event: decodeEmergencyBypassEvent(topics, data) };
    case "proposal_created_event":
      return { name: "ProposalCreatedEvent", event: decodeProposalCreatedEvent(topics, data) };
    case "report_dismissed_event":
      return { name: "ReportDismissedEvent", event: decodeReportDismissedEvent(topics, data) };
    case "treasury_updated_event":
      return { name: "TreasuryUpdatedEvent", event: decodeTreasuryUpdatedEvent(topics, data) };
    case "pool_admin_removed_event":
      return { name: "PoolAdminRemovedEvent", event: decodePoolAdminRemovedEvent(topics, data) };
    case "proposal_executed_event":
      return { name: "ProposalExecutedEvent", event: decodeProposalExecutedEvent(topics, data) };
    case "appeal_resolved":
      return { name: "GovAppealResolvedEvent", event: decodeGovAppealResolvedEvent(topics, data) };
    case "gov_proposal_vetoed_event":
      return { name: "GovProposalVetoedEvent", event: decodeGovProposalVetoedEvent(topics, data) };
    case "credential_verified_event":
      return {
        name: "CredentialVerifiedEvent",
        event: decodeCredentialVerifiedEvent(topics, data),
      };
    case "gov_proposal_created_event":
      return {
        name: "GovProposalCreatedEvent",
        event: decodeGovProposalCreatedEvent(topics, data),
      };
    case "post_content_hash_set_event":
      return {
        name: "PostContentHashSetEvent",
        event: decodePostContentHashSetEvent(topics, data),
      };
    case "attestation_verified_event":
      return {
        name: "AttestationVerifiedEvent",
        event: decodeAttestationVerifiedEvent(topics, data),
      };
    case "gov_proposal_executed_event":
      return {
        name: "GovProposalExecutedEvent",
        event: decodeGovProposalExecutedEvent(topics, data),
      };
    case "pool_threshold_updated_event":
      return {
        name: "PoolThresholdUpdatedEvent",
        event: decodePoolThresholdUpdatedEvent(topics, data),
      };
    case "credential_root_updated_event":
      return {
        name: "CredentialRootUpdatedEvent",
        event: decodeCredentialRootUpdatedEvent(topics, data),
      };
    case "post_removed_by_moderation_event":
      return {
        name: "PostRemovedByModerationEvent",
        event: decodePostRemovedByModerationEvent(topics, data),
      };
    case "withdrawal_slippage_exceeded":
      return {
        name: "WithdrawalSlippageExceededEvent",
        event: decodeWithdrawalSlippageExceededEvent(topics, data),
      };
    default:
      return null;
  }
}
